"""JWT authentication, password hashing, and FastAPI dependencies."""
from __future__ import annotations

import uuid
from datetime import datetime, timedelta, timezone

from fastapi import Depends, HTTPException, status
from fastapi.security import HTTPAuthorizationCredentials, HTTPBearer
from jose import JWTError, jwt
from passlib.context import CryptContext
from sqlalchemy.orm import Session

from app.config import settings
from app.database import get_db

pwd_context = CryptContext(schemes=["bcrypt"], deprecated="auto")
bearer_scheme = HTTPBearer()

VALID_ROLES = {"PLATFORM_ADMIN", "TENANT_ADMIN", "TRADER", "RESEARCHER", "RISK_MANAGER", "VIEWER"}
VALID_TENANT_STATUSES = {"ACTIVE", "SUSPENDED", "READ_ONLY", "DISABLED"}
VALID_TRADING_MODES = {"BACKTEST", "REPLAY", "PAPER", "SHADOW", "LIVE"}


def hash_password(password: str) -> str:
    """Hash a plaintext password."""
    return pwd_context.hash(password)


def verify_password(plain: str, hashed: str) -> bool:
    """Verify a plaintext password against a hash."""
    return pwd_context.verify(plain, hashed)


def create_access_token(user_id: uuid.UUID, tenant_id: uuid.UUID | None, role: str) -> str:
    """Create a signed JWT access token."""
    expire = datetime.now(timezone.utc) + timedelta(minutes=settings.jwt_expire_minutes)
    payload = {
        "sub": str(user_id),
        "tenant_id": str(tenant_id) if tenant_id else None,
        "role": role,
        "exp": expire,
    }
    return jwt.encode(payload, settings.jwt_secret, algorithm=settings.jwt_algorithm)


def get_current_user(
    creds: HTTPAuthorizationCredentials = Depends(bearer_scheme),
    db: Session = Depends(get_db),
):
    """FastAPI dependency: decode JWT and return the User row."""
    from app.models import User

    try:
        payload = jwt.decode(creds.credentials, settings.jwt_secret, algorithms=[settings.jwt_algorithm])
    except JWTError:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Invalid token")

    user_id = payload.get("sub")
    if not user_id:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Invalid token payload")

    user = db.query(User).filter(User.id == uuid.UUID(user_id), User.is_active.is_(True)).first()
    if not user:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="User not found or inactive")
    return user


def require_role(*allowed_roles: str):
    """FastAPI dependency factory: restrict endpoint to specific roles."""

    def checker(current_user=Depends(get_current_user)):
        if current_user.role not in allowed_roles:
            raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="Insufficient permissions")
        return current_user

    return checker


def require_tenant_access(tenant_id: uuid.UUID, current_user=Depends(get_current_user)):
    """FastAPI dependency: ensure the user belongs to the requested tenant (or is platform admin)."""
    if current_user.role == "PLATFORM_ADMIN":
        return current_user
    if current_user.tenant_id != tenant_id:
        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="Access denied to this tenant")
    return current_user

"""Strategy management endpoints (platform and tenant-owned)."""
from __future__ import annotations

import uuid

from fastapi import APIRouter, Depends, HTTPException, status
from sqlalchemy.orm import Session

from app.auth import get_current_user, require_role
from app.audit import record_audit
from app.database import get_db
from app.models import Strategy, Tenant, User
from app.schemas import StrategyCreate, StrategyResponse, StrategyUpdate

router = APIRouter(prefix="/strategies", tags=["strategies"])


@router.get("", response_model=list[StrategyResponse])
def list_strategies(
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    """List strategies visible to the current user.
    Platform strategies (owner_type=PLATFORM) are visible to all.
    Tenant strategies are visible only to members of that tenant.
    Platform admins see everything."""
    if current_user.role == "PLATFORM_ADMIN":
        return db.query(Strategy).order_by(Strategy.name).all()

    return (
        db.query(Strategy)
        .filter(
            (Strategy.owner_type == "PLATFORM")
            | (Strategy.tenant_id == current_user.tenant_id)
        )
        .order_by(Strategy.name)
        .all()
    )


@router.post("", response_model=StrategyResponse, status_code=status.HTTP_201_CREATED)
def create_strategy(
    body: StrategyCreate,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    """Create a strategy.
    - owner_type=PLATFORM, tenant_id=None: requires PLATFORM_ADMIN
    - owner_type=TENANT, tenant_id set: requires TENANT_ADMIN or RESEARCHER in that tenant
    """
    if body.owner_type == "PLATFORM":
        if current_user.role != "PLATFORM_ADMIN":
            raise HTTPException(
                status_code=status.HTTP_403_FORBIDDEN,
                detail="Only platform admins can create platform strategies",
            )
        if body.tenant_id is not None:
            raise HTTPException(
                status_code=status.HTTP_400_BAD_REQUEST,
                detail="Platform strategies must not have a tenant_id",
            )
    elif body.owner_type == "TENANT":
        if body.tenant_id is None:
            raise HTTPException(
                status_code=status.HTTP_400_BAD_REQUEST,
                detail="Tenant strategies must specify a tenant_id",
            )
        if current_user.role not in ("PLATFORM_ADMIN", "TENANT_ADMIN", "RESEARCHER"):
            raise HTTPException(
                status_code=status.HTTP_403_FORBIDDEN,
                detail="Insufficient permissions to create tenant strategies",
            )
        if current_user.role != "PLATFORM_ADMIN" and current_user.tenant_id != body.tenant_id:
            raise HTTPException(
                status_code=status.HTTP_403_FORBIDDEN,
                detail="Access denied to this tenant",
            )
        tenant = db.query(Tenant).filter(Tenant.id == body.tenant_id).first()
        if not tenant:
            raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Tenant not found")
    else:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="owner_type must be PLATFORM or TENANT",
        )

    strategy = Strategy(
        tenant_id=body.tenant_id,
        name=body.name,
        description=body.description,
        version=body.version,
        owner_type=body.owner_type,
        code_reference=body.code_reference,
    )
    db.add(strategy)
    db.flush()

    record_audit(
        db,
        action="strategy_created",
        tenant_id=body.tenant_id,
        user_id=current_user.id,
        resource=f"strategy:{strategy.id}",
        after_state=body.model_dump(mode="json"),
    )
    db.commit()
    db.refresh(strategy)
    return strategy


@router.get("/{strategy_id}", response_model=StrategyResponse)
def get_strategy(
    strategy_id: uuid.UUID,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    """Get a single strategy. Checks visibility."""
    strategy = db.query(Strategy).filter(Strategy.id == strategy_id).first()
    if not strategy:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Strategy not found")

    if strategy.owner_type == "TENANT" and current_user.role != "PLATFORM_ADMIN":
        if current_user.tenant_id != strategy.tenant_id:
            raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="Access denied")

    return strategy


@router.patch("/{strategy_id}", response_model=StrategyResponse)
def update_strategy(
    strategy_id: uuid.UUID,
    body: StrategyUpdate,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    """Update a strategy. Ownership check enforced."""
    strategy = db.query(Strategy).filter(Strategy.id == strategy_id).first()
    if not strategy:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Strategy not found")

    # Ownership check
    if strategy.owner_type == "PLATFORM":
        if current_user.role != "PLATFORM_ADMIN":
            raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="Only platform admins can update platform strategies")
    else:
        if current_user.role not in ("PLATFORM_ADMIN", "TENANT_ADMIN", "RESEARCHER"):
            raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="Insufficient permissions")
        if current_user.role != "PLATFORM_ADMIN" and current_user.tenant_id != strategy.tenant_id:
            raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="Access denied")

    before = {"name": strategy.name, "version": strategy.version, "status": strategy.status}
    updates = body.model_dump(exclude_unset=True)
    for key, value in updates.items():
        setattr(strategy, key, value)
    db.flush()

    record_audit(
        db,
        action="strategy_updated",
        tenant_id=strategy.tenant_id,
        user_id=current_user.id,
        resource=f"strategy:{strategy_id}",
        before_state=before,
        after_state=updates,
    )
    db.commit()
    db.refresh(strategy)
    return strategy

